head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.init = function() {
    var jsonData = [{
            "col1": "0",
            "col2": "test"
        }, {
            "col1": "0",
            "col2": "test"
        },
        {
            "col1": "0"
        }, {
            "col1": "0"
        },
        {
            "col1": "0"
        }, {
            "col1": "0"
        },
        {
            "col1": "0"
        }, {
            "col1": "0"
        },
        {
            "col1": "0"
        }, {
            "col1": "0"
        },
        {
            "col1": "0"
        }, {
            "col1": "0"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.__isMerged = function() {
    var b = true;
    ((j) => j.length ? j : $('#mf_wq_uuid_3_body_tbody tr'))($('#wq_uuid_3_body_tbody tr')).not(".w2grid_hidedRow").find("td[col_id='col1']").each(function(i, el) {
        if (i != 2 && i != 0) {
            if (scwin.__getJq(this).find("input").length) {
                b = false;
            }
        }
    });
    return b;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
}
